// Retained observations are hints for a fresh read; none can directly create a packet or Apply.
async fn recheck_hold(c:&mut PgConnection,number:&str)->Value {
    let mut work=execution_enqueue(c,number).await;work["stage"]=json!("NEEDS_INPUT");work["status"]=json!("waiting");work["reason"]=json!("applicant_count_requires_review");work["facts"]=json!({"posted_at":chrono::Utc::now().to_rfc3339(),"applicants_min":10,"applicants_max":10,"experience_min":0,"experience_max":2});work["profile_version"]=json!(3);browser_save(c,&format!("apply_work:{}",work["id"].as_str().unwrap()),work.clone()).await;work
}
async fn recheck_hint(c:&mut PgConnection)->Value {let value=json!({"id":Uuid::new_v4(),"status":"pending","cursor":null,"checked":0,"fresh_reads":0});browser_save(c,"apply_filter_recheck",value.clone()).await;value}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_filter_reconsideration_can_only_queue_a_fresh_read_and_retains_identity_history(){
    let(mut c,_,_)=sync_fixture(json!([])).await;sqlx::query("UPDATE candidate_profiles SET verified_experience_years=0").execute(&mut c).await.unwrap();let before=recheck_hold(&mut c,"123456789012").await;let hint=recheck_hint(&mut c).await;assert!(automated_apply_agents::execution::reconsideration::tick(&mut c).await.unwrap());let work=browser_pref(&mut c,&format!("apply_work:{}",before["id"].as_str().unwrap())).await;assert_eq!(work["id"],before["id"]);assert_eq!(work["operation"],"inspect_job");assert_eq!(work["stage"],"DISCOVERED");assert_eq!(work["status"],"queued");assert_eq!(work["admitted_actions"],json!([]));assert!(work["packet_id"].is_null());assert!(work["binding"].is_null());assert!(work["profile_version"].is_null());assert_eq!(work["last_filter_recheck"]["request_id"],hint["id"]);assert_eq!(work["last_filter_recheck"]["retained_facts_only"],true);assert!(!automated_apply_agents::execution::reconsideration::tick(&mut c).await.unwrap());assert_eq!(browser_pref(&mut c,"apply_filter_recheck").await["status"],"complete");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_filter_reconsideration_skips_spent_and_receipt_bound_work_without_refunding_admissions(){
    let(mut c,_,_)=sync_fixture(json!([])).await;let mut spent=recheck_hold(&mut c,"123456789012").await;spent["admitted_actions"]=json!([{"fingerprint":"apply:spent"}]);let key=format!("apply_work:{}",spent["id"].as_str().unwrap());browser_save(&mut c,&key,spent.clone()).await;let protected=recheck_hold(&mut c,"223456789012").await;browser_save(&mut c,"naukri_receipt:223456789012",json!({"damaged":true})).await;recheck_hint(&mut c).await;assert!(!automated_apply_agents::execution::reconsideration::tick(&mut c).await.unwrap());assert_eq!(browser_pref(&mut c,&key).await,spent);assert_eq!(browser_pref(&mut c,&format!("apply_work:{}",protected["id"].as_str().unwrap())).await,protected);assert_eq!(browser_pref(&mut c,"apply_filter_recheck").await["checked"],0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_filter_reconsideration_does_not_advance_past_an_eligible_read_waiting_for_capacity(){
    let(mut c,_,_)=sync_fixture(json!([])).await;sqlx::query("UPDATE candidate_profiles SET verified_experience_years=0").execute(&mut c).await.unwrap();let held=recheck_hold(&mut c,"123456789012").await;execution_enqueue(&mut c,"223456789012").await;let mut config=browser_pref(&mut c,"application_queue_policy").await;config["policy"]["max_pending"]=json!(1);browser_save(&mut c,"application_queue_policy",config).await;recheck_hint(&mut c).await;assert!(!automated_apply_agents::execution::reconsideration::tick(&mut c).await.unwrap());let hint=browser_pref(&mut c,"apply_filter_recheck").await;assert!(hint["cursor"].is_null());assert!(hint["retry_after"].is_string());assert_eq!(hint["checked"],0);assert_eq!(browser_pref(&mut c,&format!("apply_work:{}",held["id"].as_str().unwrap())).await,held);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_filter_reconsideration_yields_to_owner_lock_and_honors_stop_before_mutation(){
    let(mut c,_,_)=sync_fixture(json!([])).await;recheck_hold(&mut c,"123456789012").await;recheck_hint(&mut c).await;let before=browser_snapshot(&mut c).await;let mut other=connection().await;let mut held=other.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *held).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();assert!(!automated_apply_agents::execution::reconsideration::tick(&mut c).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);held.rollback().await.unwrap();let mut config=browser_pref(&mut c,"application_queue_policy").await;config["state"]=json!("STOPPED");browser_save(&mut c,"application_queue_policy",config).await;let stopped=browser_snapshot(&mut c).await;assert!(!automated_apply_agents::execution::reconsideration::tick(&mut c).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,stopped);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_filter_reconsideration_failed_event_ack_rolls_back_cursor_and_all_work_changes(){
    let(mut c,_,_)=sync_fixture(json!([])).await;sqlx::query("UPDATE candidate_profiles SET verified_experience_years=0").execute(&mut c).await.unwrap();recheck_hold(&mut c,"123456789012").await;recheck_hint(&mut c).await;let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_recheck_event_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'apply_event:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_recheck_event_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_recheck_event_drop()").execute(&mut c).await.unwrap();assert_eq!(automated_apply_agents::execution::reconsideration::tick(&mut c).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_recheck_event_drop ON owner_preferences;DROP FUNCTION fixture_recheck_event_drop()").execute(&mut c).await.unwrap();
}
